 const arcs=Array.from({length:12},(_,i)=>{
  const a=polar(i*30,116),b=polar((i+1)*30,116),m=polar(i*30+15,99);
  return `<path d="M ${a[0].toFixed(2)} ${a[1].toFixed(2)} A116 116 0 0 1 ${b[0].toFixed(2)} ${b[1].toFixed(2)}" stroke="${idx===i?'#6bdefd':'#5b618e'}" stroke-width="${idx===i?8:2}" fill="none"/><text x="${m[0].toFixed(2)}" y="${(m[1]+7).toFixed(2)}" fill="${idx===i?'#f8dd8e':'#b8bedb'}" text-anchor="middle" font-size="26">${ZODIAC_GLYPHS[i]}</text>`;
 }).join('');
