   if(pos<0)return `<div class="palace-cell empty" aria-hidden="true"></div>`;
   const branch=['巳','午','未','申','辰','','','酉','卯','','','戌','寅','丑','子','亥'][i];const m=c.ziwei.status==='ok'?c.ziwei.palaces.find(p=>p.branch===branch):null;
