function renderMethods(c){$('methodGrid').innerHTML=MODULES.map(m=>{const [cls,label]=methodState(m,c);let value='';if(m.id==='ziwei'&&c.ziwei?.status==='ok')value=`十二宮已排出 · ${c.ziwei.stars}顆主星`;if(m.id==='liuyao'&&coin?.najia)value=`${coin.najia.palace}宮 · ${coin.najia.stage} · 世${coin.najia.world}應${coin.najia.response}`;if(m.id==='tarotDraw'&&tarotDrawn)value=`已抽取 ${tarotDrawn.cards.length} 張牌`;if(m.id==='bazi')value=`三柱：${c.bazi.year&&c.bazi.month?`${c.bazi.year}·${c.bazi.month}·${c.bazi.day}`:'交界待確認'}`;if(m.id==='western')value=`太陽：${c.sun||'交界待確認'}`;if(m.id==='vedic')value=c.sky.status==='ok'?`月宿：${c.sky.vedic.nakshatra}`:`太陽：${c.vedic||'交界待確認'}（日期近似）`;if(m.id==='numerology')value=`生命道路 ${c.num.life} · 生日 ${c.num.birthday}`;if(m.id==='tarotBirth')value=`生日牌 ${c.tarot.expression}`;if(m.id==='nineStar')value=`本命：${c.nine?.name||'交界待確認'}`;if(m.id==='maya')value=`卓爾金 ${c.my.tz}`;if(m.id==='iching'&&coin)value=`${coin.hex} · ${coin.moving?.length||0} 動爻`;if(m.id==='meihua'&&plum)value=`${plum.primary?.title||plum.up+plum.low} · 第 ${plum.move} 爻動`;return `<article class="mod" data-system="${safe(m.id)}"><div class="mod-top"><div class="mod-icon" aria-hidden="true">${safe(m.icon)}</div><span class="stat ${cls}">${label}</span></div><h3>${safe(m.name)}</h3><p>${safe(m.desc)}</p>${value?`<strong class="smalltxt">${safe(value)}</strong>`:''}<details class="details"><summary>查看計算範圍</summary><p>${safe(m.detail)}</p></details></article>`}).join('');$('methodsCount').textContent=`${MODULES.length} 個核心模組`}
function updateCoverage(c){$('coverage').textContent=`${c.coverage}%`;$('coverageBar').style.width=`${c.coverage}%`;$('coverageMessage').textContent=`已計算權重 ${c.coverage}% · 尚未可用 ${100-c.coverage}%`}
function renderWeights(c){$('weightList').innerHTML=MODULES.map(m=>{const [cl,st]=methodState(m,c);return `<div class="weight-row"><label for="w-${m.id}">${safe(m.name)} <span class="stat ${cl}" style="font-size:10px;padding:2px 5px">${c.ready[m.id]?'可用':'需資料'}</span></label><input type="range" id="w-${m.id}" data-weight="${m.id}" min="0" max="50" value="${weights[m.id]}" step="1" aria-label="${safe(m.name)} 權重"><b>${weights[m.id]}%</b></div>`}).join('');updateCoverage(c);$('weightList').querySelectorAll('input[data-weight]').forEach(el=>el.addEventListener('input',e=>{rebalance(e.target.dataset.weight,Number(e.target.value));$('weightList').querySelectorAll('input[data-weight]').forEach(x=>{x.value=weights[x.dataset.weight];x.nextElementSibling.textContent=weights[x.dataset.weight]+'%'});renderQuick(true);if(generated)renderReport(false)}))}
function rebalance(id,newV){const others=Object.keys(weights).filter(x=>x!==id),total=others.reduce((s,k)=>s+weights[k],0),rest=100-newV;let proposed=others.map(k=>({key:k,raw:total?weights[k]/total*rest:rest/others.length})),floor=proposed.map(x=>Math.floor(x.raw)),left=rest-floor.reduce((a,b)=>a+b,0),order=proposed.map((x,i)=>({i,fract:x.raw-floor[i]})).sort((a,b)=>b.fract-a.fract);for(let i=0;i<left;i++)floor[order[i].i]++;weights[id]=newV;others.forEach((k,i)=>weights[k]=floor[i]);}
