function extendedReport(c){const s=c.sky,questions={overview:'哪些象徵和你的實際經驗相符？哪些完全不符？請各記下一例。',career:'你目前最需要的是穩定累積、公開表達，還是嘗試新方向？用一次小型行動驗證。',love:'你希望被如何理解？把期待轉成一件對方能觀察到的具體行動。',wealth:'把想像中的機會寫成可驗證假設，再核對成本、流動性與可承受損失。',year:'選一個今年想完成的主題，設定能追蹤的里程碑。命理象徵不當作事件預報。'};let html=`<section class="report-block"><h3>主題反思 · ${safe($('topic').selectedOptions[0].textContent)}</h3><div class="topic-reflection"><b>把象徵帶回生活</b><p>${safe(questions[$('topic').value])}</p></div></section>`;if(s.status==='ok'&&(weights.western>0||weights.vedic>0)){html+=`<section class="report-block"><h3>你的行星星圖</h3><p class="muted smalltxt">UTC ${safe(s.utc)} · ${safe(s.civil.timezone)} · ${safe(s.locationReason)}。Lahiri 歲差為近似模型。</p><div class="report-atlas"><div><b>西洋 · 熱帶黃道</b>${wheel(c,'western',true)}</div><div><b>印度 · 恆星黃道</b>${wheel(c,'vedic',true)}</div></div>${table(['行星','熱帶黃道','恆星黃道','整宮'],s.points.map(p=>[p.glyph+' '+p.name,SKY().signText(p.lon),SKY().signText(p.sidereal),p.house||'需座標']))}<h3>本命相位</h3>${table(['行星 A','相位','行星 B','容許度'],s.aspects.map(a=>[a.a,a.name,a.b,a.orb.toFixed(2)+'°']))}<h3>印度 D9 與大運</h3>${table(['行星','D9 Navamsa'],s.points.slice(0,7).map(p=>[p.name,SKY().signText(p.navamsa)]))}${table(['Vimshottari','起始','結束'],s.vedic.dasha.map(p=>[p.lord,p.start,p.end]))}<p class="muted smalltxt">大運採 365.2425 天／年；月宿、Pada 和大運日期均受近似歲差影響，交界需複核。</p></section>`;}if(c.luck&&weights.bazi>0)html+=`<section class="report-block"><h3>八字大運 · ${c.luck.forward?'順':'逆'}行</h3><p>約 ${c.luck.age.toFixed(2)} 歲起運，按三天折一歲。</p>${table(['大運','起始年齡','結束年齡'],c.luck.periods.map(p=>[p.pillar,p.from.toFixed(2),p.to.toFixed(2)]))}</section>`;return html;}

